50	enum class CheckMode { kNode, kBit };
51	
52	bool AbslParseFlag(std::string_view text, CheckMode* mode, std::string* error) {
53	  if (text == "node") {
54	    *mode = CheckMode::kNode;
55	    return true;
56	  }
57	  if (text == "bit") {
58	    *mode = CheckMode::kBit;
59	    return true;
60	  }
61	  *error = "unknown check mode, specify 'node' or 'bit'";
62	  return false;
63	}
64	
65	std::string AbslUnparseFlag(CheckMode mode) {
66	  return mode == CheckMode::kNode ? "node" : "bit";
67	}
