92	// Map from original proc node to its cloned Node* instances across activations.
93	using NodeActivationMap = absl::flat_hash_map<Node*, std::vector<Node*>>;
94	
95	std::vector<Node*> FilterCandidatesByName(
96	    const std::vector<Node*>& candidates,
97	    const std::vector<std::string_view>& filter_tokens) {
98	  if (filter_tokens.empty()) {
99	    return candidates;
100	  }
101	  std::vector<Node*> filtered;
102	  for (Node* n : candidates) {
103	    bool match = false;
104	    for (std::string_view tok : filter_tokens) {
105	      if (absl::StrContains(n->GetName(), tok)) {
106	        match = true;
107	        break;
108	      }
109	    }
110	    if (match) {
111	      filtered.push_back(n);
112	    }
113	  }
114	  return filtered;
115	}
116	
117	absl::StatusOr<std::vector<Node*>> FilterTargetsForChecking(
118	    const std::vector<Node*>& candidates,
119	    const NodeActivationMap& node_activations, int64_t unroll_count) {
120	  std::vector<Node*> target_nodes;
121	  for (Node* n : candidates) {
122	    auto it = node_activations.find(n);
123	    if (it == node_activations.end()) {
124	      continue;
125	    }
126	    if (it->second.size() != unroll_count) {
127	      continue;
128	    }
129	    target_nodes.push_back(n);
130	  }
131	  return target_nodes;
132	}
