134	bool IsInteractiveTty(const std::ostream& os) {
135	  if (os.rdbuf() == std::cout.rdbuf()) {
136	    return isatty(fileno(stdout));
137	  }
138	  if (os.rdbuf() == std::cerr.rdbuf()) {
139	    return isatty(fileno(stderr));
140	  }
141	  return false;
142	}
