144	// TODO: google/xls#4734 - move to gloop
145	class ProgressTracker {
146	 public:
147	  ProgressTracker(std::ostream& os, int64_t total_targets)
148	      : os_(os),
149	        total_targets_(total_targets),
150	        interactive_(IsInteractiveTty(os)) {}
151	
152	  void RenderProgress(int64_t current) {
153	    if (!interactive_) {
154	      return;
155	    }
156	    float progress = total_targets_ > 0
157	                         ? static_cast<float>(current) / total_targets_
158	                         : 1.0f;
159	    int64_t percent = static_cast<int64_t>(progress * 100);
160	    int64_t bar_width = 30;
161	    int64_t pos = static_cast<int64_t>(bar_width * progress);
162	
163	    os_ << "\r[" << std::setw(3) << percent << "%] [";
164	    for (int64_t i = 0; i < bar_width; ++i) {
165	      if (i < 10) {
166	        os_ << "\033[1;32m";  // Green
167	      } else if (i < 20) {
168	        os_ << "\033[1;97m";  // White
169	      } else {
170	        os_ << "\033[1;31m";  // Red
171	      }
172	
173	      if (i < pos) {
174	        os_ << "=";
175	      } else if (i == pos) {
176	        os_ << ">";
177	      } else {
178	        os_ << " ";
179	      }
180	    }
181	    os_ << "\033[0m] " << current << "/" << total_targets_
182	        << " nodes (Constant: " << constant_checks_;
183	    if (timeout_checks_ > 0) {
184	      os_ << ", Timeout: " << timeout_checks_;
185	    }
186	    os_ << ")" << std::flush;
187	  }
188	
189	  void RecordNonConstantCheck() { non_constant_checks_++; }
190	  void RecordConstantNode(Node* n) {
191	    constant_checks_++;
192	    if (interactive_) {
193	      os_ << "\r\033[K";
194	    }
195	    os_ << "UNSAT *** ALERT: CONSTANT NODE DETECTED ***: '" << n->GetName()
196	        << "' (" << OpToString(n->op()) << ", " << n->GetType()->ToString()
197	        << ")\n";
198	  }
199	  void RecordConstantBit(Node* n, int64_t b) {
200	    constant_checks_++;
201	    if (interactive_) {
202	      os_ << "\r\033[K";
203	    }
204	    os_ << "UNSAT *** ALERT: CONSTANT BIT DETECTED ***: '" << n->GetName()
205	        << "' bit [" << b << "]\n";
206	  }
207	  void RecordTimeoutNode(Node* n, std::string_view reason) {
208	    timeout_checks_++;
209	    if (interactive_) {
210	      os_ << "\r\033[K";
211	    }
212	    os_ << "UNKNOWN (" << (!reason.empty() ? reason : "unknown") << "): '"
213	        << n->GetName() << "' (" << OpToString(n->op()) << ")\n";
214	  }
215	  void RecordTimeoutBit(Node* n, int64_t b, std::string_view reason) {
216	    timeout_checks_++;
217	    if (interactive_) {
218	      os_ << "\r\033[K";
219	    }
220	    os_ << "UNKNOWN (" << (!reason.empty() ? reason : "unknown") << "): '"
221	        << n->GetName() << "' bit [" << b << "]\n";
222	  }
223	
224	  int64_t non_constant_checks() const { return non_constant_checks_; }
225	  int64_t constant_checks() const { return constant_checks_; }
226	  int64_t timeout_checks() const { return timeout_checks_; }
227	
228	 private:
229	  std::ostream& os_;
230	  int64_t total_targets_;
231	  bool interactive_;
232	  int64_t non_constant_checks_ = 0;
233	  int64_t constant_checks_ = 0;
234	  int64_t timeout_checks_ = 0;
235	};
236	
237	absl::Status RealMain(std::ostream& os, std::string_view ir_path,
238	                      std::string_view top_proc_name, int64_t unroll_count,
239	                      CheckMode mode, int64_t rlimit, int64_t timeout_ms,
240	                      std::string_view node_filter_str,
241	                      bool fail_on_constants) {
242	  XLS_ASSIGN_OR_RETURN(std::string ir_text, GetFileContents(ir_path));
243	  XLS_ASSIGN_OR_RETURN(std::unique_ptr<Package> package,
244	                       Parser::ParsePackage(ir_text));
245	
246	  Proc* proc = nullptr;
247	  if (top_proc_name.empty()) {
248	    XLS_ASSIGN_OR_RETURN(proc, package->GetTopAsProc());
249	  } else {
250	    XLS_ASSIGN_OR_RETURN(proc, package->GetProc(top_proc_name));
251	  }
252	
253	  os << "Loaded Proc '" << proc->name() << "' with " << proc->node_count()
254	     << " nodes.\n";
255	
256	  // Strip non-synthesizable nodes before unrolling or checking.
257	  XLS_RETURN_IF_ERROR(StripNonSynthNodes(package.get(), proc));
258	
259	  // Get candidate target nodes early so we can skip unrolling if none exist.
260	  XLS_ASSIGN_OR_RETURN(std::vector<Node*> candidates,
261	                       GetNodesFilteringNonSynthAndTrivialConstants(proc));
262	
263	  std::vector<std::string_view> filter_tokens;
264	  if (!node_filter_str.empty()) {
265	    filter_tokens = absl::StrSplit(node_filter_str, ',', absl::SkipEmpty());
266	  }
267	  candidates = FilterCandidatesByName(candidates, filter_tokens);
268	
269	  if (candidates.empty()) {
270	    os << "Constant Checks:     0\n";
271	    return absl::OkStatus();
272	  }
273	
274	  // Unroll the proc.
275	  os << "Unrolling proc " << unroll_count << " times...\n";
276	  XLS_ASSIGN_OR_RETURN((auto [unrolled_func, node_activations]),
277	                       UnrollProcForConstancy(proc, unroll_count));
278	
279	  // Translate Unrolled Function to Z3
280	  os << "Translating unrolled function to Z3 SMT AST...\n";
281	  XLS_ASSIGN_OR_RETURN(std::unique_ptr<solvers::z3::IrTranslator> translator,
282	                       solvers::z3::IrTranslator::CreateAndTranslate(
283	                           unrolled_func, /*allow_unsupported=*/true));
284	
285	  Z3_context ctx = translator->ctx();
286	  Z3_solver solver = Z3_mk_solver(ctx);
287	  Z3_solver_inc_ref(ctx, solver);
288	  Z3_params params = Z3_mk_params(ctx);
289	  Z3_params_inc_ref(ctx, params);
290	
291	  if (rlimit > 0) {
292	    translator->SetRlimit(rlimit);
293	    Z3_params_set_uint(ctx, params, Z3_mk_string_symbol(ctx, "rlimit"),
294	                       static_cast<unsigned>(rlimit));
295	  }
296	  if (timeout_ms > 0) {
297	    Z3_params_set_uint(ctx, params, Z3_mk_string_symbol(ctx, "timeout"),
298	                       static_cast<unsigned>(timeout_ms));
299	  }
300	  // Z3 swallows ctrl+c, interpreting it as a sign to cancel the current solve
301	  // rather than the whole binary.
302	  Z3_params_set_bool(ctx, params, Z3_mk_string_symbol(ctx, "ctrl_c"), false);
303	
304	  Z3_solver_set_params(ctx, solver, params);
305	
306	  XLS_ASSIGN_OR_RETURN(
307	      std::vector<Node*> target_nodes,
308	      FilterTargetsForChecking(candidates, node_activations, unroll_count));
309	
310	  os << "Verifying " << target_nodes.size()
311	     << " non-literal, synthesizable nodes in mode '" << AbslUnparseFlag(mode)
312	     << "'...\n\n";
313	
314	  ProgressTracker progress_tracker(os, target_nodes.size());
315	  progress_tracker.RenderProgress(0);
316	
317	  for (int64_t idx = 0; idx < target_nodes.size(); ++idx) {
318	    Node* n = target_nodes[idx];
319	    const std::vector<Node*>& act_nodes = node_activations[n];
320	
321	    if (mode == CheckMode::kNode) {
322	      std::vector<Z3_ast> disequalities;
323	      disequalities.reserve(act_nodes.size() - 1);
324	      Z3_ast ast_0 = translator->GetTranslation(act_nodes[0]);
325	      for (int64_t i = 1; i < act_nodes.size(); ++i) {
326	        Z3_ast ast_i = translator->GetTranslation(act_nodes[i]);
327	        Z3_ast eq = Z3_mk_eq(ctx, ast_0, ast_i);
328	        disequalities.push_back(Z3_mk_not(ctx, eq));
329	      }
330	
331	      Z3_ast can_change =
332	          Z3_mk_or(ctx, disequalities.size(), disequalities.data());
333	
334	      Z3_lbool check_res = Z3_solver_check_assumptions(
335	          ctx, solver, /*num_assumptions=*/1, /*assumptions=*/&can_change);
336	
337	      if (check_res == Z3_L_TRUE) {
338	        progress_tracker.RecordNonConstantCheck();
339	      } else if (check_res == Z3_L_FALSE) {
340	        progress_tracker.RecordConstantNode(n);
341	        // Performance optimization: permanently assert proven constants into
342	        // the shared solver at decision level 0. Because target nodes are
343	        // checked in topological order, Z3's congruence-closure and bit-vector
344	        // engines instantly merge constant operand ASTs across activations into
345	        // the same equivalence class, allowing downstream checks to simplify
346	        // without re-exploring the proof trees of their operands.
347	        Z3_solver_assert(ctx, solver, Z3_mk_not(ctx, can_change));
348	      } else {
349	        const char* reason = Z3_solver_get_reason_unknown(ctx, solver);
350	        progress_tracker.RecordTimeoutNode(
351	            n, reason != nullptr ? reason : "unknown");
352	      }
353	    } else {
354	      // Bit mode: check each bit index b independently
355	      int64_t width = n->GetType()->GetFlatBitCount();
356	
357	      // Collect flat bit ASTs for each activation
358	      std::vector<std::vector<Z3_ast>> act_flat_bits;
359	      act_flat_bits.reserve(act_nodes.size());
360	      for (Node* act_node : act_nodes) {
361	        Z3_ast ast = translator->GetTranslation(act_node);
362	        act_flat_bits.push_back(
363	            FlattenBitsOnly(ctx, translator.get(), n->GetType(), ast));
364	      }
365	
366	      for (int64_t b = 0; b < width; ++b) {
367	        bool skip = false;
368	        for (int64_t i = 0; i < act_flat_bits.size(); ++i) {
369	          if (b >= act_flat_bits[i].size()) {
370	            skip = true;
371	            break;
372	          }
373	        }
374	        if (skip) {
375	          continue;
376	        }
377	
378	        std::vector<Z3_ast> disequalities;
379	        disequalities.reserve(act_flat_bits.size() - 1);
380	        for (int64_t i = 1; i < act_flat_bits.size(); ++i) {
381	          Z3_ast eq = Z3_mk_eq(ctx, act_flat_bits[0][b], act_flat_bits[i][b]);
382	          disequalities.push_back(Z3_mk_not(ctx, eq));
383	        }
384	
385	        Z3_ast can_change =
386	            Z3_mk_or(ctx, disequalities.size(), disequalities.data());
387	
388	        Z3_lbool check_res = Z3_solver_check_assumptions(
389	            ctx, solver, /*num_assumptions=*/1, /*assumptions=*/&can_change);
390	
391	        if (check_res == Z3_L_TRUE) {
392	          progress_tracker.RecordNonConstantCheck();
393	        } else if (check_res == Z3_L_FALSE) {
394	          progress_tracker.RecordConstantBit(n, b);
395	          // Performance optimization: permanently assert proven constant bits
396	          // into the shared solver at decision level 0. Downstream bit-vector
397	          // operations can immediately exploit these constant bit assignments
398	          // without re-exploring the proof trees of their operands.
399	          Z3_solver_assert(ctx, solver, Z3_mk_not(ctx, can_change));
400	        } else {
401	          const char* reason = Z3_solver_get_reason_unknown(ctx, solver);
402	          progress_tracker.RecordTimeoutBit(
403	              n, b, reason != nullptr ? reason : "unknown");
404	        }
405	      }
406	    }
407	    progress_tracker.RenderProgress(idx + 1);
408	  }
409	
410	  os << "\r\033[K";  // Clear progress bar before printing summary
411	
412	  os << "\n=== Verification Summary ===\n"
413	     << "Check Mode:          " << AbslUnparseFlag(mode) << "\n"
414	     << "Non-Constant Checks: " << progress_tracker.non_constant_checks()
415	     << "\n"
416	     << "Constant Checks:     " << progress_tracker.constant_checks()
417	     << " (Potential Static Flops)\n"
418	     << "Timeout Checks:      " << progress_tracker.timeout_checks() << "\n";
419	
420	  Z3_params_dec_ref(ctx, params);
421	  Z3_solver_dec_ref(ctx, solver);
422	
423	  if (fail_on_constants && progress_tracker.constant_checks() > 0) {
424	    return absl::FailedPreconditionError(absl::StrFormat(
425	        "Found %d constant nodes/bits.", progress_tracker.constant_checks()));
426	  }
427	
428	  return absl::OkStatus();
429	}
430	
431	}  // namespace
432	}  // namespace xls
433	
434	int main(int argc, char** argv) {
435	  xls::InitXls(argv[0], argc, argv);
436	  std::string ir_path = absl::GetFlag(FLAGS_ir_path);
437	  QCHECK(!ir_path.empty()) << "--ir_path must be specified.";
438	
439	  int64_t unroll_count = absl::GetFlag(FLAGS_unroll_count);
440	  QCHECK_GT(unroll_count, 1)
441	      << "--unroll_count must be > 1 as there must be at least two activations "
442	         "to check for constancy.";
443	
444	  std::string top_proc_name = absl::GetFlag(FLAGS_top_proc);
445	  CheckMode mode = absl::GetFlag(FLAGS_mode);
446	  int64_t rlimit = absl::GetFlag(FLAGS_z3_rlimit);
447	  int64_t timeout_ms = absl::GetFlag(FLAGS_z3_timeout_ms);
448	  std::string node_filter_str = absl::GetFlag(FLAGS_node_filter);
449	  bool fail_on_constants = absl::GetFlag(FLAGS_fail_on_constants);
450	  return xls::ExitStatus(xls::RealMain(std::cout, ir_path, top_proc_name,
451	                                       unroll_count, mode, rlimit, timeout_ms,
452	                                       node_filter_str, fail_on_constants));
453	}
