#ifndef XLS_IR_PROC_TESTUTILS_H_
#define XLS_IR_PROC_TESTUTILS_H_

#include <cstdint>
#include <optional>
#include <vector>

#include "absl/container/flat_hash_map.h"
#include "absl/status/statusor.h"
#include "xls/ir/bits.h"
#include "xls/ir/channel.h"
