proc test_proc {
    out_ch: chan<u32> out;

    config(out_ch: chan<u32> out) { (out_ch,) }

    init { u32:0 }

    next(st: u32) {
        let const_zero = st & u32:0;
        let trailing_zero = st << u32:2;
        let add1 = st + u32:1 + const_zero + (trailing_zero & u32:0);
        assert!(st == st, "test assert");
        let tok = send(join(), out_ch, add1);
        add1
    }
}

