47	// Returns true if `n` is trivially constant by construction (i.e. a Literal or
48	// a tree of operations whose inputs are exclusively Literals, with no path from
49	// dynamic inputs like Receive or StateRead).
50	//
51	// Aggregate types that are literal are often constructed from their literal
52	// elements rather than making a single aggregate-typed literal. We want to
53	// avoid spurious "non-constant" detections in these cases.
54	//
55	// Note that `non_constant_nodes` must contain every one of `n`'s operands for
56	// which `IsConstantByConstruction(op)` is true in order to evaluate
57	// `IsConstantByConstruction(n)` correctly. This can be achieved by calling
58	// `IsConstantByConstruction` on the nodes in topological order, inserting
59	// constant nodes into the set as we go.
60	bool IsConstantByConstruction(
61	    Node* n, const absl::flat_hash_set<Node*>& constant_nodes) {
62	  if (n->Is<Literal>()) {
63	    return true;
64	  }
65	  if (n->OpIn({Op::kReceive, Op::kStateRead, Op::kParam, Op::kSend, Op::kNext,
66	               Op::kAssert, Op::kTrace, Op::kCover})) {
67	    return false;
68	  }
69	  return absl::c_all_of(n->operands(), [&](Node* operand) {
70	    return constant_nodes.contains(operand);
71	  });
72	}
