88	  absl::flat_hash_set<Node*> constant_nodes;
89	  std::vector<Node*> target_nodes;
90	  for (Node* n : sorted_nodes) {
91	    if (IsConstantByConstruction(n, constant_nodes)) {
92	      constant_nodes.insert(n);
93	      continue;
94	    }
95	    if (n->GetType()->IsToken() || n->GetType()->GetFlatBitCount() == 0) {
96	      continue;
97	    }
98	    if (n->OpIn({Op::kParam, Op::kStateRead, Op::kReceive, Op::kSend, Op::kNext,
99	                 Op::kAssert, Op::kTrace, Op::kCover})) {
100	      continue;
101	    }
102	    target_nodes.push_back(n);
103	  }
104	  return target_nodes;
105	}
