108	    Proc* proc, int64_t activation_count) {
109	  XLS_ASSIGN_OR_RETURN(
110	      UnrolledProc unrolled,
111	      UnrollProc(proc, activation_count, /*include_state=*/true,
112	                 Value::Tuple({Value(UBits(0xdeadbeef, 32))}),
113	                 /*cleanup=*/false));
114	
115	  NodeActivationMap node_activations;
116	  for (const ActivationAction& act : unrolled.activations) {
117	    for (const auto& [orig_node, val] : act.node_values) {
118	      if (val.node() != nullptr) {
119	        node_activations[orig_node].push_back(val.node());
120	      }
121	    }
122	  }
123	  return std::make_pair(unrolled.function, node_activations);
124	}
