126	std::vector<Z3_ast> FlattenBitsOnly(Z3_context ctx,
127	                                    solvers::z3::IrTranslator* translator,
128	                                    Type* type, Z3_ast value) {
129	  if (type->IsBits()) {
130	    return translator->FlattenValue(type, value);
131	  }
132	  if (type->IsTuple()) {
133	    TupleType* tuple_type = type->AsTupleOrDie();
134	    Z3_sort tuple_sort = Z3_get_sort(ctx, value);
135	    std::vector<Z3_ast> all_bits;
136	    for (int64_t i = 0; i < tuple_type->size(); ++i) {
137	      Type* elem_type = tuple_type->element_type(i);
138	      Z3_func_decl proj_fn = Z3_get_tuple_sort_field_decl(ctx, tuple_sort, i);
139	      Z3_ast elem_ast = Z3_mk_app(ctx, proj_fn, 1, &value);
140	      std::vector<Z3_ast> elem_bits =
141	          FlattenBitsOnly(ctx, translator, elem_type, elem_ast);
142	      all_bits.insert(all_bits.end(), elem_bits.begin(), elem_bits.end());
143	    }
144	    return all_bits;
145	  }
146	  if (type->IsArray()) {
147	    ArrayType* array_type = type->AsArrayOrDie();
148	    Z3_sort array_sort = Z3_get_sort(ctx, value);
149	    Z3_sort domain_sort = Z3_get_array_sort_domain(ctx, array_sort);
150	    std::vector<Z3_ast> all_bits;
151	    for (int64_t i = 0; i < array_type->size(); ++i) {
152	      Z3_ast idx_ast = Z3_mk_unsigned_int64(ctx, i, domain_sort);
153	      Z3_ast elem_ast = Z3_mk_select(ctx, value, idx_ast);
154	      std::vector<Z3_ast> elem_bits = FlattenBitsOnly(
155	          ctx, translator, array_type->element_type(), elem_ast);
156	      all_bits.insert(all_bits.end(), elem_bits.begin(), elem_bits.end());
